'use client'

import { useState } from 'react'

import { toast } from 'sonner'
import { Avatar, AvatarFallback, AvatarImage } from '@astrale-os/ui/avatar'
import { Card, CardContent } from '@astrale-os/ui/card'
import { Sortable, SortableItem, SortableItemHandle } from '@/components/ui/sortable'
import { GripVerticalIcon } from "lucide-react"

interface TeamMember {
  id: string
  name: string
  fallback: string
  src: string
}

const defaultMembers: TeamMember[] = [
  {
    id: '1',
    name: 'Phillip George',
    fallback: 'PG',
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-1.png'
  },
  {
    id: '2',
    name: 'Jaylon Donin',
    fallback: 'JD',
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-2.png'
  },
  {
    id: '3',
    name: 'Tiana Curtis',
    fallback: 'TC',
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-3.png'
  },
  {
    id: '4',
    name: 'Zaire Vetrovs',
    fallback: 'ZV',
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-4.png'
  },
  {
    id: '5',
    name: 'Kianna Philips',
    fallback: 'KP',
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-5.png'
  },
  {
    id: '6',
    name: 'Santino Pratt',
    fallback: 'SP',
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-6.png'
  },
  {
    id: '7',
    name: 'Kiera Wallace',
    fallback: 'KW',
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-7.png'
  },
  {
    id: '8',
    name: 'Damon Pierce',
    fallback: 'DP',
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-8.png'
  }
]

const SortableAvatarDemo = () => {
  const [members, setMembers] = useState<TeamMember[]>(defaultMembers)
  const [hovered, setHovered] = useState<string | null>(null)

  const handleValueChange = (newMembers: TeamMember[]) => {
    setMembers(newMembers)

    toast.success('Items reordered successfully!', {
      description: newMembers.map((member, index) => `${index + 1}. ${member.name}`).join(', ')
    })
  }

  return (
    <Card>
      <CardContent>
        <Sortable
          value={members}
          onValueChange={handleValueChange}
          getItemValue={member => member.id}
          strategy='horizontal'
          className='flex flex-wrap items-center gap-3'
        >
          {members.map(member => (
            <SortableItem key={member.id} value={member.id}>
              <div
                className='relative'
                onMouseEnter={() => setHovered(member.id)}
                onMouseLeave={() => setHovered(null)}
                onFocus={() => setHovered(member.id)}
                onBlur={() => setHovered(null)}
              >
                <div className='flex flex-col items-center gap-2'>
                  <Avatar className='size-12 rounded-full'>
                    <AvatarImage src={member.src} alt={member.name} className='rounded-full' />
                    <AvatarFallback>{member.fallback}</AvatarFallback>
                  </Avatar>
                  <h4 className='text-muted-foreground truncate text-center text-sm'>{member.name}</h4>
                </div>
                <SortableItemHandle
                  className={
                    hovered === member.id
                      ? 'bg-background text-muted-foreground pointer-events-auto absolute -top-1 left-1/2 z-10 -translate-x-1/2 rounded-full border p-1 opacity-100 shadow-xs transition-opacity'
                      : 'bg-background text-muted-foreground pointer-events-none absolute -top-1 left-1/2 z-10 -translate-x-1/2 rounded-full border p-1 opacity-0 shadow-xs transition-opacity'
                  }
                >
                  <GripVerticalIcon className='size-3' />
                </SortableItemHandle>
              </div>
            </SortableItem>
          ))}
        </Sortable>
      </CardContent>
    </Card>
  )
}

export default SortableAvatarDemo

'use client'

import * as React from 'react'
import type { CSSProperties, HTMLAttributes, ReactElement, ReactNode } from 'react'
import {
  Children,
  cloneElement,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useLayoutEffect,
  useMemo,
  useState
} from 'react'

import {
  defaultDropAnimationSideEffects,
  DndContext,
  DragOverlay,
  KeyboardSensor,
  MeasuringStrategy,
  MouseSensor,
  TouchSensor,
  useSensor,
  useSensors
} from '@dnd-kit/core'
import type {
  DragEndEvent,
  DragStartEvent,
  DropAnimation,
  Modifiers,
  UniqueIdentifier,
  DraggableSyntheticListeners
} from '@dnd-kit/core'
import type { AnimateLayoutChanges } from '@dnd-kit/sortable'
import {
  arrayMove,
  defaultAnimateLayoutChanges,
  rectSortingStrategy,
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy
} from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { Slot } from 'radix-ui'
import { createPortal } from 'react-dom'

import { cn } from '@astrale-os/ui/class-name'

// Sortable Item Context
const SortableItemContext = createContext<{
  listeners: DraggableSyntheticListeners | undefined
  isDragging?: boolean
  disabled?: boolean
}>({
  listeners: undefined,
  isDragging: false,
  disabled: false
})

const IsOverlayContext = createContext(false)

const SortableInternalContext = createContext<{
  activeId: UniqueIdentifier | null
  modifiers?: Modifiers
}>({
  activeId: null,
  modifiers: undefined
})

const animateLayoutChanges: AnimateLayoutChanges = args => defaultAnimateLayoutChanges({ ...args, wasDragging: true })

const dropAnimationConfig: DropAnimation = {
  sideEffects: defaultDropAnimationSideEffects({
    styles: {
      active: {
        opacity: '0.4'
      }
    }
  })
}

// Multipurpose Sortable Component
export interface SortableRootProps<T> extends Omit<HTMLAttributes<HTMLDivElement>, 'onDragStart' | 'onDragEnd'> {
  value: T[]
  onValueChange: (value: T[]) => void
  getItemValue: (item: T) => string
  children: ReactNode
  onMove?: (event: { event: DragEndEvent; activeIndex: number; overIndex: number }) => void
  strategy?: 'horizontal' | 'vertical' | 'grid'
  onDragStart?: (event: DragStartEvent) => void
  onDragEnd?: (event: DragEndEvent) => void
  modifiers?: Modifiers
  asChild?: boolean
}

function Sortable<T>({
  value,
  onValueChange,
  getItemValue,
  className,
  asChild = false,
  onMove,
  strategy = 'vertical',
  onDragStart,
  onDragEnd,
  modifiers,
  children,
  ...props
}: SortableRootProps<T>) {
  const [activeId, setActiveId] = useState<UniqueIdentifier | null>(null)
  const [mounted, setMounted] = useState(false)

  useLayoutEffect(() => setMounted(true), [])

  const sensors = useSensors(
    useSensor(MouseSensor, {
      activationConstraint: {
        distance: 10
      }
    }),
    useSensor(TouchSensor, {
      activationConstraint: {
        delay: 250,
        tolerance: 5
      }
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates
    })
  )

  const handleDragStart = useCallback(
    (event: DragStartEvent) => {
      setActiveId(event.active.id)
      onDragStart?.(event)
    },
    [onDragStart]
  )

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event

      setActiveId(null)
      onDragEnd?.(event)

      if (!over) return

      // Handle item reordering
      const activeIndex = value.findIndex((item: T) => getItemValue(item) === active.id)

      const overIndex = value.findIndex((item: T) => getItemValue(item) === over.id)

      if (activeIndex !== overIndex) {
        if (onMove) {
          onMove({ event, activeIndex, overIndex })
        } else {
          const newValue = arrayMove(value, activeIndex, overIndex)

          onValueChange(newValue)
        }
      }
    },
    [value, getItemValue, onValueChange, onMove, onDragEnd]
  )

  const handleDragCancel = useCallback(() => {
    setActiveId(null)
  }, [])

  const getStrategy = () => {
    switch (strategy) {
      case 'horizontal':
        return rectSortingStrategy
      case 'grid':
        return rectSortingStrategy
      case 'vertical':
      default:
        return verticalListSortingStrategy
    }
  }

  const itemIds = useMemo(() => value.map(getItemValue), [value, getItemValue])

  const contextValue = useMemo(() => ({ activeId, modifiers }), [activeId, modifiers])

  // Find the active child for the overlay
  const overlayContent = useMemo(() => {
    if (!activeId) return null
    let result: ReactNode = null

    Children.forEach(children, child => {
      if (isValidElement(child) && (child.props as any).value === activeId) {
        result = cloneElement(child as ReactElement<any>, {
          ...(child.props as any),
          className: cn((child.props as any).className, 'z-50')
        })
      }
    })

    return result
  }, [activeId, children])

  const Comp = asChild ? Slot.Root : 'div'

  return (
    <SortableInternalContext.Provider value={contextValue}>
      <DndContext
        sensors={sensors}
        modifiers={modifiers}
        measuring={{
          droppable: {
            strategy: MeasuringStrategy.Always
          }
        }}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
        onDragCancel={handleDragCancel}
      >
        <SortableContext items={itemIds} strategy={getStrategy()}>
          <Comp
            data-slot='sortable'
            data-dragging={activeId !== null}
            className={cn(activeId !== null && 'cursor-grabbing!', className)}
            {...props}
          >
            {children}
          </Comp>
        </SortableContext>
        {mounted &&
          createPortal(
            <DragOverlay
              dropAnimation={dropAnimationConfig}
              modifiers={modifiers}
              className={cn('z-50', activeId && 'cursor-grabbing')}
            >
              <IsOverlayContext.Provider value={true}>{overlayContent}</IsOverlayContext.Provider>
            </DragOverlay>,
            document.body
          )}
      </DndContext>
    </SortableInternalContext.Provider>
  )
}

export interface SortableItemProps extends HTMLAttributes<HTMLDivElement> {
  value: string
  disabled?: boolean
  asChild?: boolean
}

function SortableItem({ value, className, asChild = false, disabled, children, ...props }: SortableItemProps) {
  const isOverlay = useContext(IsOverlayContext)

  const {
    setNodeRef,
    transform,
    transition,
    attributes,
    listeners,
    isDragging: isSortableDragging
  } = useSortable({
    id: value,
    disabled: disabled || isOverlay,
    animateLayoutChanges
  })

  if (isOverlay) {
    const Comp = asChild ? Slot.Root : 'div'

    return (
      <SortableItemContext.Provider value={{ listeners: undefined, isDragging: true, disabled: false }}>
        <Comp data-slot='sortable-item' data-value={value} data-dragging={true} className={cn(className)} {...props}>
          {children}
        </Comp>
      </SortableItemContext.Provider>
    )
  }

  const style = {
    transition,
    transform: CSS.Transform.toString(transform)
  } as CSSProperties

  const Comp = asChild ? Slot.Root : 'div'

  return (
    <SortableItemContext.Provider value={{ listeners, isDragging: isSortableDragging, disabled }}>
      <Comp
        data-slot='sortable-item'
        data-value={value}
        data-dragging={isSortableDragging}
        data-disabled={disabled}
        ref={setNodeRef}
        style={style}
        {...attributes}
        className={cn(isSortableDragging && 'z-50 opacity-50', disabled && 'opacity-50', className)}
        {...props}
      >
        {children}
      </Comp>
    </SortableItemContext.Provider>
  )
}

export interface SortableItemHandleProps extends HTMLAttributes<HTMLDivElement> {
  cursor?: boolean
  asChild?: boolean
}

function SortableItemHandle({
  className,
  asChild = false,
  cursor = true,
  children,
  ...props
}: SortableItemHandleProps) {
  const { listeners, isDragging, disabled } = useContext(SortableItemContext)

  const Comp = asChild ? Slot.Root : 'div'

  return (
    <Comp
      data-slot='sortable-item-handle'
      data-dragging={isDragging}
      data-disabled={disabled}
      {...listeners}
      className={cn(cursor && (isDragging ? 'cursor-grabbing!' : 'cursor-grab!'), className)}
      {...props}
    >
      {children}
    </Comp>
  )
}

export interface SortableOverlayProps extends Omit<React.ComponentProps<typeof DragOverlay>, 'children'> {
  children?: ReactNode | ((params: { value: UniqueIdentifier }) => ReactNode)
}

function SortableOverlay({ children, className, ...props }: SortableOverlayProps) {
  const { activeId, modifiers } = useContext(SortableInternalContext)
  const [mounted, setMounted] = useState(false)

  useLayoutEffect(() => setMounted(true), [])

  const content =
    activeId && children ? (typeof children === 'function' ? children({ value: activeId }) : children) : null

  if (!mounted) return null

  return createPortal(
    <DragOverlay
      dropAnimation={dropAnimationConfig}
      modifiers={modifiers}
      className={cn('z-50', activeId && 'cursor-grabbing', className)}
      {...props}
    >
      <IsOverlayContext.Provider value={true}>{content}</IsOverlayContext.Provider>
    </DragOverlay>,
    document.body
  )
}

export { Sortable, SortableItem, SortableItemHandle, SortableOverlay }
